package br.edu.scoa.academico.dominio.documentos;
import java.time.Instant;
public record DocumentoAcademico(long id,long alunoId,long tipoDocumentoId,String nomeOriginal,String tipoMime,long tamanhoBytes,String chaveArmazenamento,SituacaoDocumento situacao,String justificativa,Instant enviadoEm,long revisao){public DocumentoAcademico{if(id<0||alunoId<=0||tipoDocumentoId<=0||nomeOriginal==null||nomeOriginal.isBlank()||tipoMime==null||tamanhoBytes<=0||chaveArmazenamento==null||chaveArmazenamento.isBlank()||situacao==null||enviadoEm==null||revisao<0||(id==0)!=(revisao==0))throw new IllegalArgumentException("Documento inválido");if(situacao==SituacaoDocumento.RECUSADO&&(justificativa==null||justificativa.isBlank()))throw new IllegalArgumentException("Recusa exige justificativa");}public DocumentoAcademico aprovar(){if(situacao!=SituacaoDocumento.PENDENTE)throw new IllegalStateException("Documento não pendente");return new DocumentoAcademico(id,alunoId,tipoDocumentoId,nomeOriginal,tipoMime,tamanhoBytes,chaveArmazenamento,SituacaoDocumento.APROVADO,"",enviadoEm,revisao+1);}public DocumentoAcademico recusar(String motivo){return new DocumentoAcademico(id,alunoId,tipoDocumentoId,nomeOriginal,tipoMime,tamanhoBytes,chaveArmazenamento,SituacaoDocumento.RECUSADO,motivo,enviadoEm,revisao+1);}}
